def transform(A: str, B: str) -> int:
    if sorted(A) != sorted(B):
        return -1

    n = len(A)
    min_steps = float('inf')

    for i in range(n):
        if A[i:] + A[:i] == B:
            min_steps = min(min_steps, i)

    return min_steps
